using System;
using System.Diagnostics;
using System.Drawing;
using System.IO;
using System.Linq;
using System.Text;
using System.Threading.Tasks;
using System.Windows.Forms;
namespace Overclock {
 sealed partial class MainWindow {
  public void BeginHdrCompactTest(string folder){Directory.CreateDirectory(folder);Shown+=async(s,e)=>{var log=new StringBuilder();Action<string> capture=name=>{BringToFront();Activate();Refresh();Application.DoEvents();using(var bitmap=new Bitmap(Width,Height)){using(var g=Graphics.FromImage(bitmap))g.CopyFromScreen(Location,Point.Empty,Size);bitmap.Save(Path.Combine(folder,name+"-actual.png"));}};Action validate=()=>{var list=Descendants(body).OfType<DarkListBox>().FirstOrDefault();StudioDevice device=list==null?null:list.SelectedItem as StudioDevice;if(device==null){var selector=Descendants(body).OfType<DarkCombo>().FirstOrDefault(c=>c.AccessibleName=="Compact display selector");if(selector==null||selector.Items.Count==0)throw new Exception("Compact display selector missing");}var check=Descendants(body).OfType<CheckBox>().Single(c=>c.Text.StartsWith("Enable HDR"));if(device!=null&&check.Enabled!=device.HdrCanToggle)throw new Exception("HDR capability gate mismatch");log.AppendLine("PASS HDR checkbox: "+check.Text+"; enabled="+check.Enabled);};try{TopMost=true;Navigate("Display Studio");await Task.Delay(14000);validate();capture("Display-HDR");ToggleMini();await Task.Delay(14000);foreach(var dimensions in new[]{new Size(860,610),new Size(640,520)}){Size=dimensions;await Task.Delay(300);validate();if(Descendants(body).OfType<StudioSlider>().Count()!=2||tiles.Count!=3)throw new Exception("Compact telemetry or monitor sliders missing");DarkScrolling.Audit(this);var selector=Descendants(body).OfType<DarkCombo>().Single(c=>c.AccessibleName=="Compact display selector");var row=selector.Parent;var peers=row.Controls.Cast<Control>().Where(c=>c.Visible).ToArray();for(int a=0;a<peers.Length;a++){if(peers[a].Left<0||peers[a].Right>row.ClientSize.Width)throw new Exception("Compact header extends beyond row");for(int b=a+1;b<peers.Length;b++)if(peers[a].Bounds.IntersectsWith(peers[b].Bounds))throw new Exception("Compact header controls overlap");}capture("Compact-"+Width+"x"+Height);log.AppendLine("PASS compact live brightness, contrast, temperature, HDR, Restore and three telemetry cards at "+Size);}ToggleMini();if(compact||page!="Overview")throw new Exception("Expand monitor failed");log.AppendLine("PASS compact expand/navigation; no HDR or monitor writes performed.");}catch(Exception error){Environment.ExitCode=1;log.AppendLine("FAIL "+error);}File.WriteAllText(Path.Combine(folder,"hdr-compact-results.txt"),log.ToString());Close();};}
  public void BeginLiveBrightnessTest(string folder){Directory.CreateDirectory(folder);Shown+=async(s,e)=>{var log=new StringBuilder();StudioDevice selected=null;int? original=null;try{Navigate("Display Studio");await Task.Delay(14000);var view=Descendants(body).OfType<StudioView>().Single();var list=Descendants(body).OfType<DarkListBox>().First();selected=list.SelectedItem as StudioDevice;if(selected==null||!selected.Brightness.HasValue)throw new Exception("No supported brightness control");original=selected.Brightness.Value;var slider=Descendants(body).OfType<StudioSlider>().Single(x=>x.Caption=="Brightness");if(!slider.Enabled||Descendants(body).OfType<CheckBox>().Any(x=>x.Text=="Enable explicit hardware changes"))throw new Exception("Default brightness control/removed checkbox regression");var edit=typeof(StudioSlider).GetMethod("OnKeyDown",System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Instance);Keys direction=original<100?Keys.Right:Keys.Left;int target=original.Value+(direction==Keys.Right?1:-1);for(int i=0;i<20;i++)edit.Invoke(slider,new object[]{new KeyEventArgs(i%2==0?direction:direction==Keys.Right?Keys.Left:Keys.Right)});edit.Invoke(slider,new object[]{new KeyEventArgs(direction)});await Task.Delay(200);var watch=Stopwatch.StartNew();while(!view.LiveBrightnessIdle&&watch.ElapsedMilliseconds<12000)await Task.Delay(50);var read=await studios.Display.Execute(new StudioCommand{Action="brightness-read",Id=selected.Id},System.Threading.CancellationToken.None);if(read.Error!=null||read.Devices.Single().Brightness!=target)throw new Exception("Live slider did not reach latest requested value");log.AppendLine("PASS real monitor brightness "+original+" -> "+target+" from rapid slider edits, without Apply or opt-in. Slider remained enabled: "+slider.Enabled);edit.Invoke(slider,new object[]{new KeyEventArgs(direction==Keys.Right?Keys.Left:Keys.Right)});await Task.Delay(200);watch.Restart();while(!view.LiveBrightnessIdle&&watch.ElapsedMilliseconds<12000)await Task.Delay(50);read=await studios.Display.Execute(new StudioCommand{Action="brightness-read",Id=selected.Id},System.Threading.CancellationToken.None);if(read.Error!=null||read.Devices.Single().Brightness!=original)throw new Exception("Live restoration failed");log.AppendLine("PASS original brightness restored by slider to "+original+"%.");original=null;}catch(Exception error){Environment.ExitCode=1;log.AppendLine("FAIL "+error);}if(original.HasValue&&selected!=null){try{var result=await studios.Display.Execute(new StudioCommand{Action="brightness-live",Id=selected.Id,Brightness=original},System.Threading.CancellationToken.None);log.AppendLine(result.Error==null?"RECOVERY original brightness restored":"RECOVERY FAILED: "+result.Error);}catch(Exception ex){log.AppendLine("RECOVERY FAILED: "+ex.Message);}}File.WriteAllText(Path.Combine(folder,"live-brightness-results.txt"),log.ToString());Close();};}
  protected override void WndProc(ref Message message){base.WndProc(ref message);if(message.Msg==0x7e||message.Msg==0x219||message.Msg==0x218){foreach(var view in Descendants(body).OfType<StudioView>().ToArray())view.InvalidateDevices();}}
  public void BeginStudioUiTest(string folder,bool connectRgb=false){Directory.CreateDirectory(folder);Shown+=async(s,e)=>{var log=new StringBuilder();try{TopMost=true;WindowState=FormWindowState.Normal;await Task.Delay(1000);foreach(var size in new[]{new Size(1586,992),new Size(1100,760),new Size(900,720)}){Size=size;foreach(string route in new[]{"RGB Studio","Display Studio"}){Navigate(route);if(connectRgb&&route=="RGB Studio"){Descendants(body).OfType<Button>().Single(b=>b.Text=="Connect").PerformClick();await Task.Delay(3500);}await Task.Delay(route=="Display Studio"?14000:700);if(IsDisposed)return;PerformLayout();DarkScrolling.Audit(this);navBar.AssertLayout();var chosen=Descendants(body).OfType<DarkListBox>().Select(list=>list.SelectedItem as StudioDevice).FirstOrDefault(d=>d!=null);if(connectRgb&&route=="RGB Studio"&&chosen==null)throw new Exception("RGB real provider did not populate the UI");if(chosen!=null){if(route=="Display Studio")foreach(var slider in Descendants(body).OfType<StudioSlider>()){bool expected=slider.Caption=="Brightness"?chosen.Brightness.HasValue:slider.Caption=="Contrast"?chosen.Contrast.HasValue:false;if(expected&&!slider.Enabled)throw new Exception("Readable monitor control disabled: "+slider.Caption);}log.AppendLine("PASS real UI selection "+chosen.Name+"; "+chosen.Status);}BringToFront();Activate();Refresh();Application.DoEvents();using(var bitmap=new Bitmap(Width,Height)){using(var g=Graphics.FromImage(bitmap))g.CopyFromScreen(Location,Point.Empty,Size);bitmap.Save(Path.Combine(folder,route.Replace(" ","-")+"-"+size.Width+"-actual.png"));}log.AppendLine("PASS actual "+route+" at "+Size+"; DPI="+DeviceDpi+"; dark-scrollbar audit and navigation layout");foreach(var label in Descendants(body).OfType<Label>().Where(x=>x.Text.Contains("Unavailable / operation failed")))log.AppendLine("PROVIDER STATE: "+label.Text);}}using(var provider=new DisplayStudioClient()){var reply=await provider.Execute(new StudioCommand(),System.Threading.CancellationToken.None);File.WriteAllText(Path.Combine(folder,"display-readonly-discovery.json"),StudioJson.Serialize(reply));log.AppendLine(string.IsNullOrEmpty(reply.Error)?"PASS read-only supervised Windows discovery: "+reply.Devices.Count+" display(s)":"BLOCKED display discovery: "+reply.Error);}log.AppendLine("No RGB/DDC/ICC writes, SSD-write benchmarks or GPU stress were executed. DPI values above identify actual host DPI; other physical DPI modes require separate validation.");}catch(Exception ex){Environment.ExitCode=1;log.AppendLine("FAIL "+ex);}finally{File.WriteAllText(Path.Combine(folder,"results.txt"),log.ToString());Close();}};}
 }
}
